// (wider distances may result in greater differences
vec3 dx = ( GetBlur1(uv + vec2( 1.0 , 0.0 )*d) - GetBlur1(uv-vec2( 1.0 , 0.0 )*d).xy ); // east-west gradient
vec3 dy = ( GetBlur1(uv + vec2( 0.0 , 1.0 )*d) - GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy ); // north-south gradient
vec2 dither_uv = uv_orig*uTexSize.xy*texsize_noise_lq.zw * 1.2 // makes the graininess of the fur
// 0.5 (very raw) - 3.0 (fine leather)
+ rand_frame.xy;    // needs to be set to keep an overall randomness
vec2 uv_bg = mix(uv_orig,uv,0.4)   // scaling the input motion vector down, useful for a lower layer
+ vec2(dx.x,dy.x)*(vec2(1.0)/uTexSize) * 2.0; // important: this is the spreading factor.
// 1 to 8 are good values
// (dependent on the distance the gradient is taken from)
ret.x = GetPixel(uv_bg).x // we will process the value from the previous uFrame
- (GetPixel(uv_bg).x - GetBlur3(uv_bg).x)  * 0.02  // this part darkens the most contrasty parts only
// try differnet blur levels too
- 0.004  // overall fade to black
// the play of the upper two factors makes the 3D impact
+(texture(sampler_noise_lq, dither_uv).xyz-0.5) *0.12;  // intensity of the hairs (0.04 - 0.4)
}

